  'Language server colours identifiers by meaning, over the parser\'s own highlighting.': 'language server 按含义为标识符着色，叠加在解析器的着色之上。',
  'Allow, confirm or block a tool call by pattern. Rules are checked top to bottom and the FIRST match decides — so a rule that should always apply belongs at the top. With no matching rule, the approval mode above decides as before.': '按模式允许、确认或阻止工具调用。规则自上而下检查，第一个匹配的生效——因此应始终适用的规则放在最上面。若无匹配规则，则由批准模式照常决定。',
