  'editor.diagLens': "Inline-Diagnose-Linse",
  "Prints the diagnostic message at the end of the line, without hovering.": "Zeigt die Diagnosemeldung am Zeilenende an, ohne darauf zu zeigen.",
  'editor.gitBlame': "Inline-Git-Blame",
  "Shows who last changed each line, at the end of the line. Needs a git repository.": "Zeigt am Zeilenende, wer die Zeile zuletzt geändert hat. Erfordert ein Git-Repository.",
  'editor.lineNumbers': 'Zeilennummern',
  'Relative shows the distance from the cursor, which is what Vim-style jumps need.': 'Relativ zeigt den Abstand zum Cursor — was Vim-artige Sprünge brauchen.',
  'Absolute': 'Absolut',
  'Relative': 'Relativ',
  'Off': 'Aus',
  'editor.scrollMargin': 'Scroll-Rand',
  'Blank lines kept above and below the cursor while scrolling.': 'Leerzeilen, die beim Scrollen über und unter dem Cursor frei bleiben.',
  'editor.scrollPastEnd': 'Über das Ende scrollen',
  'Lets the last line be scrolled up to the middle of the window.': 'Erlaubt, die letzte Zeile bis zur Fenstermitte zu scrollen.',
  'editor.centeredWidth': 'Breite der zentrierten Spalte',
  'Narrow, centred text column. 0 keeps full width.': 'Schmale, zentrierte Textspalte. 0 behält die volle Breite.',
  'editor.fixAllOnSave': 'Alles beim Speichern korrigieren',
  'Runs the language server\'s "fix all" action on save. This REWRITES your code - separate from formatting.': 'Führt beim Speichern die „Alles korrigieren“-Aktion des Language Servers aus. SCHREIBT Ihren Code um — getrennt vom Formatieren.',
  'editor.gitGutter': 'Git-Änderungsbalken',
  'Bars in the gutter for lines added, changed or removed since the last commit.': 'Balken im Rand für Zeilen, die seit dem letzten Commit hinzugefügt, geändert oder entfernt wurden.',
  'editor.inlayHints': 'Inline-Hinweise',
  'Language server shows inferred types and parameter names inside the code.': 'Der Language Server zeigt abgeleitete Typen und Parameternamen im Code an.',
  'editor.semanticTokens': 'Semantische Tokens',
  'Language server colours identifiers by meaning, over the parser\'s own highlighting.': 'Der Language Server färbt Bezeichner nach ihrer Bedeutung, über der Färbung des Parsers.',
  'Allow, confirm or block a tool call by pattern. Rules are checked top to bottom and the FIRST match decides — so a rule that should always apply belongs at the top. With no matching rule, the approval mode above decides as before.': 'Erlaubt, bestätigt oder blockiert einen Tool-Aufruf per Muster. Regeln werden von oben nach unten geprüft, die ERSTE Übereinstimmung entscheidet — eine immer geltende Regel gehört also nach oben. Ohne passende Regel entscheidet der Genehmigungsmodus wie bisher.',
  'No rules. The approval mode decides every call.': 'Keine Regeln. Der Genehmigungsmodus entscheidet jeden Aufruf.',
  'Add a rule': 'Regel hinzufügen',
  'Any tool': 'Jedes Tool',
  'CLI Agents': 'CLI-Agenten',
  'CLIs that appear in the AI panel path switcher. The built-in four are always listed; these are added to them.': 'CLIs, die im Pfadumschalter des KI-Panels erscheinen. Die vier eingebauten werden immer gelistet; diese kommen hinzu.',
  'editor.formatters': 'Externe Formatierer',
  'Commands run in order after the LSP formatter. Each receives the file on stdin and returns the new text on stdout.': 'Die Befehle laufen der Reihe nach nach dem LSP-Formatierer. Jeder erhält die Datei über stdin und gibt den neuen Text über stdout zurück.',
  'editor.debugInlineValues': 'Inline-Werte des Debuggers',
  'Shows local values at the line the debugger is paused on, without opening the Variables panel.': 'Zeigt lokale Werte in der Zeile an, in der der Debugger hält, ohne das Variablen-Panel zu öffnen.',
