  "Prints the diagnostic message at the end of the line, without hovering.": "يعرض رسالة التشخيص في نهاية السطر دون تمرير المؤشر.",
  'editor.gitBlame': "git blame مضمّن",
  "Shows who last changed each line, at the end of the line. Needs a git repository.": "يعرض من غيّر كل سطر آخر مرة، في نهاية السطر. يتطلب مستودع git.",
