  'editor.fixAllOnSave': 'إصلاح الكل عند الحفظ',
  'Runs the language server\'s "fix all" action on save. This REWRITES your code - separate from formatting.': 'يشغّل إجراء "إصلاح الكل" من language server عند الحفظ. هذا يُعيد كتابة الكود — منفصل عن التنسيق.',
  'editor.gitGutter': 'أشرطة تغييرات git',
  'Bars in the gutter for lines added, changed or removed since the last commit.': 'أشرطة في الهامش للأسطر المضافة أو المعدّلة أو المحذوفة منذ آخر commit.',
  'editor.inlayHints': 'تلميحات مضمّنة',
  'Language server shows inferred types and parameter names inside the code.': 'يعرض language server الأنواع المستنتجة وأسماء الوسائط داخل الكود.',
  'editor.semanticTokens': 'رموز دلالية',
  'Language server colours identifiers by meaning, over the parser\'s own highlighting.': 'يُلوّن language server المعرّفات حسب معناها، فوق تلوين المحلّل.',
  'Allow, confirm or block a tool call by pattern. Rules are checked top to bottom and the FIRST match decides — so a rule that should always apply belongs at the top. With no matching rule, the approval mode above decides as before.': 'يسمح باستدعاء أداة أو يؤكّده أو يحظره حسب النمط. تُفحص القواعد من الأعلى إلى الأسفل والأولى المطابقة هي التي تقرّر — لذا ضع في الأعلى القاعدة التي يجب أن تنطبق دائمًا. وإن لم تُطابق أي قاعدة، يقرّر وضع الموافقة كما كان.',
  'No rules. The approval mode decides every call.': 'لا توجد قواعد. وضع الموافقة يقرّر كل استدعاء.',
  'Add a rule': 'إضافة قاعدة',
  'Any tool': 'أي أداة',
  'CLI Agents': 'وكلاء CLI',
  'CLIs that appear in the AI panel path switcher. The built-in four are always listed; these are added to them.': 'واجهات CLI التي تظهر في مبدّل المسار بلوحة الذكاء. الأربعة المضمّنة تُدرج دائمًا؛ وهذه تُضاف إليها.',
  'editor.formatters': 'منسّقات خارجية',
  'Commands run in order after the LSP formatter. Each receives the file on stdin and returns the new text on stdout.': 'تُنفَّذ الأوامر بالترتيب بعد منسّق LSP. يتلقّى كل أمر الملف عبر stdin ويعيد النص الجديد عبر stdout.',
