const DICTS: Record<string, Dict> = { id: ID, en: EN, ja: JA, ko: KO, zh: ZH, es: ES, fr: FR, de: DE, pt: PT, ar: AR };

/**
 * English text -> the Indonesian key it is the translation of.
 *
 * `EN` is the only block that maps Indonesian key -> English text, so reading
 * it backwards turns an English call site into the Indonesian key the rest of
 * the dictionaries are filed under. `translate()` consults this when a key is
 * not found directly, which is what stops `tr('Stop')` from rendering English
 * in the Indonesian interface.
 *
 * Built lazily and cached: the dictionaries are only complete after
 * `muatKamusTambahan()` has resolved, and building this on every `tr()` would
 * walk ~2700 entries per render. `EXTRA` is read once per build and the cache is
 * thrown away when the extra dictionary arrives, so the index always covers both
 * files.
 */
let indeksInggris: Map<string, string> | null = null;
let indeksDariExtra: Record<string, Dict> | null = null;

function enKeId(): Map<string, string> {
  if (indeksInggris && indeksDariExtra === EXTRA) return indeksInggris;
  const m = new Map<string, string>();
  /*
   * EN from i18n.ts first, then i18n-extra.ts, so the earlier (hand-written)
   * entries win and the index is stable no matter which file added a key last.
   */
  for (const sumber of [EN, EXTRA.en ?? {}]) {
    for (const [k, v] of Object.entries(sumber)) {
      if (!v || v === k) continue;
      if (!m.has(v)) m.set(v, k);
    }
  }
  indeksInggris = m;
  indeksDariExtra = EXTRA;
  return m;
}

export const UI_LANGS: { value: string; label: string }[] = [
  { value: 'id', label: 'Indonesia' },
  { value: 'en', label: 'English' },
  { value: 'ja', label: '日本語' },
  { value: 'ko', label: '한국어' },
  { value: 'zh', label: '中文' },
  { value: 'es', label: 'Español' },
  { value: 'fr', label: 'Français' },
  { value: 'de', label: 'Deutsch' },
  { value: 'pt', label: 'Português' },
  { value: 'ar', label: 'العربية' },
];

let EXTRA: Record<string, Record<string, string>> = {};

/**
 * Pemuat kamus tambahan, dipanggil SEKALI dan tidak pernah dilewatkan.
 *
 * ## Kenapa ini diperbaiki
 *
 * Fungsi ini dulu hanya DIDEFINISIKAN; tidak ada satu pun pemanggilnya. Kamus
 * `i18n-extra.ts` berisi ribuan terjemahan - dan hampir semua terjemahan
 * Inggris yang benar untuk kunci Indonesia tinggal di sana, bukan di `DICTS.en`
 * yang kecil.
 *
 * Akibatnya: selama EXTRA kosong, `translate()` tidak menemukan terjemahannya
 * di kamus bahasa tujuan, lalu jatuh ke kamus dasar Indonesia dan mengembalikan
 * teks Indonesia apa adanya. Yang terlihat user persis seperti yang dilaporkan:
 * antarmuka English yang DI SANA-SINI masih Indonesia - dan campurannya
 * tampak acak, karena hanya kunci yang kebetulan ada di `DICTS.en` terlihat
 * benar.
 *
 * ## Kenapa promise, bukan flag boolean
 *
 * Beberapa komponen bisa memanggil `translate` pada frame yang sama, dan
 * masing-masing akan memicu pemuatan kalau penandanya hanya boolean - jadi
 * berkas 1.4 MB di-import berkali-kali. Promise disimpan supaya permintaan
 * kedua dan seterusnya menunggu yang pertama, bukan memulai yang baru.
 */
let janjiKamus: Promise<void> | null = null;

export function muatKamusTambahan(): Promise<void> {
  if (!janjiKamus) {
    janjiKamus = import('./i18n-extra')
      .then((m) => {
        EXTRA = m.EXTRA as unknown as Record<string, Record<string, string>>;
        /* Tandai bahwa kamus sudah siap, supaya hook di bawah bisa memicu
           render ulang. Tanpa ini, komponen yang diterjemahkan SEBELUM kamus
           tiba akan menyimpan teks Indonesianya sampai ada sebab lain untuk
           render ulang - dan bagi user itu terlihat seperti terjemahan yang
           gagal permanen. */
        kamusSiap = true;
        for (const dengar of pendengarKamus) {
          try {
            dengar();
          } catch {
            /* satu pendengar yang gagal tidak boleh membatalkan yang lain */
          }
        }
        pendengarKamus.clear();
      })
      .catch(() => {
        /* Dibiarkan kosong dengan sadar: aplikasi tetap harus jalan, hanya
           dengan terjemahan yang lebih sedikit. Yang penting kegagalannya
           TIDAK diam - ia dicatat, karena kamus yang gagal dimuat adalah
           keadaan yang harus terlihat saat pengembangan. */
        EXTRA = {};
        // eslint-disable-next-line no-console
        console.error('[i18n] gagal memuat kamus tambahan - sebagian teks akan jatuh ke bahasa sumber');
      });
  }
  return janjiKamus;
}

/** Apakah kamus tambahan sudah termuat. Dibaca hook di bawah. */
let kamusSiap = false;

/** Pendengar yang ingin diberi tahu saat kamus selesai dimuat. */
const pendengarKamus = new Set<() => void>();

export function kamusTambahanSiap(): boolean {
  return kamusSiap;
}

/**
 * Berlangganan kabar "kamus sudah siap". Mengembalikan fungsi pembatalan.
 *
 * Dipakai hook terjemahan: terjemahan pertama bisa terjadi sebelum kamus tiba,
 * dan hasilnya tidak boleh terkunci seperti itu.
 */
export function saatKamusSiap(fn: () => void): () => void {
  if (kamusSiap) {
    fn();
    return () => undefined;
  }
  pendengarKamus.add(fn);
  return () => pendengarKamus.delete(fn);
}

export function translate(lang: string, key: string): string {

  // The target-language dictionary ALWAYS wins. SRC is only the English dictionary for keys
  // whose original text is Indonesian; it used to be that SRC was checked first, so any
  // key present in SRC always showed English even when the JA/KO/
  // ES/… translation was already available - that was the cause of "switch language and it is still English
  // Inggris".
  const own = EXTRA[lang]?.[key] ?? DICTS[lang]?.[key];

  /*
   * An IDENTITY entry is a placeholder, not a translation.
   *
   * The Indonesian block is full of `'Stop': 'Stop'`, `'History': 'History'`,
   * `'Run': 'Run'` - 1588 of its 2400 entries in i18n-extra.ts are the key
   * repeated. They exist because the generator that wrote that block filed every
   * English string under itself. For `lang === 'id'` such an entry says nothing
   * ("the Indonesian for 'Stop' is 'Stop'"), and returning it early is what kept
   * the real Indonesian - `'Matikan'`, `'Riwayat'`, `'Jalankan'` - from being
   * found through the English index below. So for Indonesian an identity entry is
   * treated as "no entry" and the lookup continues; for every other language it
   * is a legitimate answer and is returned as before.
   */
  const identitas = own !== undefined && own === key;
  if (own !== undefined && !(lang === 'id' && identitas)) return own;

  /*
   * The same string, called by its ENGLISH text.
   *
   * The dictionaries are keyed on the Indonesian text (`'Matikan'`, `'Riwayat'`,
   * `'Sembunyikan panel AI'`), but plenty of call sites pass the English text
   * (`tr('Stop')`, `tr('History')`, `tr('Hide AI panel')`). Those keys are not
   * in the dictionary under that spelling, so the lookup fell all the way
   * through to the last resort and `translate()` returned the English text
   * unchanged - the Indonesian interface rendered "Stop" and "History" while
   * `tr('Matikan')` right next to it rendered correctly. That is the mixed
   * language the user reported, and it is a lookup failure, not missing data:
   * the Indonesian entry for those strings was already in the dictionary, filed
   * under its Indonesian key.
   *
   * `EN` is the one block that maps Indonesian key -> English text, so it is
   * also the reverse index: English text -> Indonesian key. Translating THAT
   * key gives every language the same answer as the Indonesian call site, with
   * no second copy of any string.
   *
   * Built lazily and cached - this runs on every `tr()` in every render, and
   * walking ~2700 entries per lookup would be a real cost.
   */
  const lewatInggris = enKeId().get(key);
  if (lewatInggris !== undefined && lewatInggris !== key) {
    const v = EXTRA[lang]?.[lewatInggris] ?? DICTS[lang]?.[lewatInggris];
    if (v !== undefined) {
      /*
       * For Indonesian the Indonesian KEY is itself the text (`'Matikan'`), so
       * a value that is only the English placeholder we started from
       * (`'Sembunyikan panel AI' => 'Hide AI panel'`) is skipped in favour of the
       * key. A symbolic key (`'nav.settings'`) keeps its value, because there the
       * value is the readable text and the key is not.
       */
      if (lang === 'id' && v === key) return lewatInggris;
      return v;
    }
    if (lang === 'id') return lewatInggris;
  }

  if (own !== undefined) return own;
  const src = SRC[key];
  if (src !== undefined) return lang === 'id' ? key : src;
  // Indonesian first, then Indonesian.
  //
  // DICTS.id was at one point the last resort, and that was dangerous: a key that only
  // exists in the ID dictionary leaked into ALL languages. As long as its value happened to be
  // English nothing looked broken - until a key was written in
  // Indonesian, and that menu showed up in Indonesian in the English, Japanese,
  // and so on without a trace. id is still included so that no text is
  // vanish altogether, but the order is now correct.
  //
  // URUTAN INI DIPERBAIKI. Dulu baris terakhirnya:
  //
  //   return EXTRA.en?.[key] ?? DICTS.en[key] ?? DICTS.id[key] ?? key;
  //
  // `DICTS.en` di baris itu adalah kamus DASAR - bukan kamus Inggris
  // terjemahan. Ia memuat pasangan seperti `'Berjalan': 'Running'`, yaitu
  // kunci Indonesia dengan nilai Inggris. Jadi untuk kunci yang HANYA ada di
  // kamus dasar, SEMUA bahasa jatuh ke situ dan menampilkan bahasa Inggris.
  //
  // Gejalanya halus dan menyesatkan: di bahasa Indonesia, badge status muncul
  // "Running" padahal kamusnya ada dan sudah diterjemahkan; di bahasa Jepang
  // pun "Running". Terlihat seperti kunci yang hilang, padahal kuncinya ada -
  // yang salah cuma urutan pencariannya.
  //
  // Sekarang bahasa aktif dicoba pada kamus dasarnya LEBIH DULU, dan bahasa
  // Inggris hanya dipakai sebagai jaring terakhir saat benar-benar tidak ada
  // apa pun.
  return (
    EXTRA[lang]?.[key] ??
    DICTS[lang]?.[key] ??
    DICTS.en[key] ??
    DICTS.id[key] ??
    key
  );
}

/**
 * Release note / changelog text can be multi-language: if `notes` is a JSON
 * object { en, id, ja, ... } pick according to the active language (falling back to en). If it is
 * not JSON, return it as-is (the old behaviour).
 */
export function catatanUntukBahasa(notes: string | null | undefined, lang: string): string {
  if (!notes) return '';
  const s = notes.trim();
  if (!s.startsWith('{')) return notes;
  try {
    const obj = JSON.parse(s) as Record<string, string>;
    if (obj && typeof obj === 'object' && !Array.isArray(obj)) {
      return obj[lang] ?? obj.en ?? Object.values(obj)[0] ?? notes;
    }
  } catch {
    /* not JSON - use it as-is */
  }
  return notes;
}

export function useT(): (key: string) => string {
  const lang = useStore((s) => s.settings.general.uiLang);
  /*
   * Muat kamus tambahan dari sini, dan render ulang saat ia tiba.
   *
   * Hook ini adalah satu-satunya tempat yang PASTI dilewati setiap komponen
   * yang menampilkan teks terjemahan - jadi ini titik yang benar untuk memicu
   * pemuatan, alih-alih menaruhnya di satu tempat startup yang mudah
   * terlupakan (dan memang sudah terlupakan: itulah bug asalnya).
   *
   * `versi` sengaja dipakai sebagai pemicu render: saat kamus selesai dimuat,
   * nilainya berubah, komponen render ulang, dan terjemahan yang tadi jatuh ke
   * bahasa Indonesia diganti dengan yang benar.
   */
  const [versi, setVersi] = useState(0);
  useEffect(() => {
    void muatKamusTambahan();
    return saatKamusSiap(() => setVersi((v) => v + 1));
  }, []);
  void versi;
  return (key: string) => translate(lang, key);
}

export function tx(key: string): string {
  return translate(useStore.getState().settings.general.uiLang, key);
}

export function tf(key: string, isi: Record<string, string | number>): string {
  let teks = tx(key);
  for (const [k, v] of Object.entries(isi)) {
    teks = teks.split(`{${k}}`).join(String(v));
  }
  return teks;
}

export function useTf(): (key: string, isi: Record<string, string | number>) => string {
  const tr = useT();
  return (key, isi) => {
    let teks = tr(key);
    for (const [k, v] of Object.entries(isi)) {
      teks = teks.split(`{${k}}`).join(String(v));
    }
    return teks;
  };
}
